//! Black-box parity with openEMS over the XML feature-coverage sweep
//! (design §5.16.3): primitives, transformations, priorities, materials
//! and weighting functions, parameters, excitations, probe and dump boxes,
//! boundary spellings, absorbing sheets and FDTD settings.
//!
//! Every case `tests/fixtures/openems/sweep_<case>/` holds a hand-written
//! `model.xml` and the openEMS v0.37 (be30220) output files listed on the `keep:`
//! line of its `meta.txt` (regenerated by
//! `scripts/openems-oracle/gen-sweep.sh`, never by the test suite). ems
//! reads the model with openEMS's reading rules
//! ([`ems::io::openems::read_model`]), runs it, writes its probe and dump
//! files the openEMS way and compares:
//!
//! * the set of probe and dump files written (the `files:` line: probes
//!   openEMS skips or splits must be skipped or split the same way);
//! * per kept probe file: the coordinate header lines exactly, the sample
//!   times, and the values (relative L2 difference over all value columns
//!   below the case's tolerance);
//! * per kept HDF5 dump (feature `hdf5`): the structure and the values
//!   (largest difference relative to the largest value of each dataset).
//!
//! Most models are a 20³-cell PEC box of 1 mm cells with a soft Gaussian
//! line source, 600 steps of 1.5 ps. With openEMS's summation order of the
//! curl (`CurlOrder::OpenEms`) models in vacuum and metal give the same
//! fields bit for bit (agreement to the printed digits); models with
//! dielectrics agree to ~3e-5, where the update coefficients of the edges
//! on a material boundary differ from openEMS's by an `f32` ulp and the
//! round-off accumulates over the ring-down. The tolerances are a few
//! times the measured agreement.
#![cfg(feature = "xml")]

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use ems::io::openems::{ProbeDomain, ProbeFile, read_model};
use ems::{CompileOptions, Simulation};

#[cfg(feature = "hdf5")]
#[path = "common/h5cmp.rs"]
mod h5cmp;

fn fixture(case: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/openems")
        .join(format!("sweep_{case}"))
}

/// The values of the `key:` line of a case's `meta.txt`.
fn meta(case: &str, key: &str) -> String {
    let p = fixture(case).join("meta.txt");
    let text = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    let pre = format!("{key}:");
    text.lines()
        .find_map(|l| l.strip_prefix(&pre).map(|v| v.trim().to_string()))
        .unwrap_or_default()
}

/// Runs ems on the case and writes its files into a fresh directory.
fn run(case: &str) -> PathBuf {
    let out = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("openems_sweep")
        .join(case);
    let _ = std::fs::remove_dir_all(&out);
    std::fs::create_dir_all(&out).unwrap();
    let (doc, _) = read_model(fixture(case).join("model.xml")).expect("model");
    let mut sim =
        Simulation::from_document_with(&doc, &CompileOptions::default(), |f| f.threads(1))
            .expect("compile");
    let res = sim.run().expect("run");
    let dt: f64 = meta(case, "dt").parse().expect("dt in meta.txt");
    assert!(
        (res.dt() / dt - 1.0).abs() < 1e-5,
        "{case}: ems dt {:e} vs openEMS {dt:e}",
        res.dt()
    );
    ems::io::openems::write_probes(&res, &out).unwrap();
    #[cfg(feature = "hdf5")]
    for d in res.dumps() {
        ems::io::openems::dump::write_dump(&out, d, &Default::default()).unwrap();
    }
    out
}

/// Relative L2 difference over all value columns of two probe files.
fn probe_diff(case: &str, name: &str, a: &str, b: &str) -> f64 {
    let coords = |t: &str| -> Vec<String> {
        t.lines()
            .filter(|l| l.starts_with("% start") || l.starts_with("% stop"))
            .map(str::to_string)
            .collect()
    };
    assert_eq!(coords(a), coords(b), "{case}/{name}: coordinate header");
    let (a, b) = (ProbeFile::parse(a).unwrap(), ProbeFile::parse(b).unwrap());
    assert_eq!((a.domain, a.kind), (b.domain, b.kind), "{case}/{name}");
    assert_eq!(a.rows.len(), b.rows.len(), "{case}/{name}: rows");
    let (mut num, mut den) = (0.0f64, 0.0f64);
    for (ra, rb) in a.rows.iter().zip(&b.rows) {
        assert_eq!(ra.len(), rb.len(), "{case}/{name}: columns");
        let x = ra[0];
        let scale = if a.domain == ProbeDomain::Time {
            1e-6 * x.abs().max(1e-12)
        } else {
            1e-9 * x.abs()
        };
        assert!(
            (x - rb[0]).abs() <= scale,
            "{case}/{name}: abscissa {x} vs {}",
            rb[0]
        );
        for (p, q) in ra[1..].iter().zip(&rb[1..]) {
            num += (p - q) * (p - q);
            den += p * p;
        }
    }
    if den == 0.0 {
        // Only the 0-step run has all-zero files (absolute difference).
        assert!(
            case.contains("steps0"),
            "{case}/{name}: openEMS file is all zero"
        );
        return num.sqrt();
    }
    (num / den).sqrt()
}

/// Runs `case` and returns the worst difference over its kept files.
fn worst(case: &str) -> f64 {
    let out = run(case);
    // The probe (and, with `hdf5`, dump) files: the same set.
    let want: BTreeSet<String> = meta(case, "files")
        .split_whitespace()
        .filter(|f| cfg!(feature = "hdf5") || !f.ends_with(".h5"))
        .map(str::to_string)
        .collect();
    let got: BTreeSet<String> = std::fs::read_dir(&out)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    assert_eq!(got, want, "{case}: files written");
    let mut w = 0.0f64;
    for f in meta(case, "keep").split_whitespace() {
        let d = if f.ends_with(".h5") {
            #[cfg(feature = "hdf5")]
            {
                h5cmp::compare_h5(&fixture(case).join(f), &out.join(f), &[], &[]).worst()
            }
            #[cfg(not(feature = "hdf5"))]
            continue;
        } else {
            let a = std::fs::read_to_string(fixture(case).join(f)).unwrap();
            let b = std::fs::read_to_string(out.join(f)).unwrap();
            probe_diff(case, f, &a, &b)
        };
        eprintln!("{case}/{f}: {d:.2e}");
        w = w.max(d);
    }
    w
}

fn check(case: &str, tol: f64) {
    let w = worst(case);
    assert!(w < tol, "{case}: difference {w:.3e} > {tol:e}");
}

macro_rules! cases {
    ($($name:ident: $tol:expr;)*) => {
        $(
            #[test]
            fn $name() {
                check(stringify!($name), $tol);
            }
        )*
    };
}

// Agreement measured on the committed fixtures in parentheses; "exact":
// the probe files are openEMS's to the printed digits (openEMS's curl
// order and coefficient rounding, `CurlOrder`, `CoeffRounding`).
cases! {
    // Primitives (materials: csx's sampling agrees with openEMS's edge
    // averaging to the last digit of the material dump; metal: identical
    // PEC edges, `--debug-PEC`).
    prim_multibox: 1e-6;            // (exact; f32 round-off 1.0e-5)
    prim_sphshell: 1e-6;            // (exact; f32 round-off 1.1e-5)
    prim_sphshell_metal: 1e-6;      // (exact to the printed digits, §5.16.6; 1.5e-3 with the native order)
    prim_cyl_oblique: 1e-6;         // (exact)
    prim_polygon_x: 1e-6;           // (exact)
    prim_linpoly_y: 1e-6;           // (exact)
    prim_rotpoly_partial: 1e-6;     // (exact)
    prim_polyhedron_cube: 1e-6;     // (exact)
    prim_stl: 1e-6;                 // (exact; 2.8e-5; 5e-3 with openEMS e89286f's position-dependent faces)
    prim_curve_diag: 1e-6;          // (exact)
    prim_wire: 1e-6;                // (exact)
    prim_wire_thick: 1e-6;          // (exact; 5.6e-5; closed surface since openEMS be30220)
    prim_cs_cyl_box: 1e-6;          // (exact)
    tie_sphere_metal: 1e-6;         // (exact)
    // Probes in the shadow of a metal cylinder (field ~1e-4 of the source's):
    // bit-identical fields with openEMS's summation order of the curl
    // (`CurlOrder::OpenEms`; 1.1e-2 and 8.6e-3 with the native order).
    tie_cyl_metal: 1e-6;            // (exact to the printed digits)
    tie_cylshell_metal: 1e-6;       // (exact to the printed digits)
    tie_wire_z: 1e-6;               // (exact; f32 round-off 1.5e-4)
    tie_linpoly_metal: 1e-6;        // (exact)
    // Transformations.
    tr_rotate_origin: 1e-6;         // (exact; 2.9e-5; 4.3e-3 without openEMS's inside tolerance)
    tr_matrix: 1e-6;                // (exact)
    tr_order: 1e-6;                 // (exact)
    tr_sphere: 1e-6;                // (exact; 4.0e-5; 4.7e-2 without the inside tolerance)
    // Priorities.
    prio_overlap: 1e-6;             // (exact)
    prio_metal_in_mat: 1e-6;        // (exact)
    // Materials.
    mat_aniso: 1e-6;                // (exact; f32 round-off 5e-5)
    mat_aniso_single: 1e-6;         // (exact; 0.6 with csx's reading of the short lists)
    mat_aniso_two: 1e-6;            // (exact; did not run: ε_z = 0)
    mat_weight_aniso: 1e-6;         // (exact)
    mat_weight_coords: 1e-4;
    mat_mue_sigma: 1e-6;            // (exact; 2.3e-5; 6e-3 with csx's arithmetic σ_m average)
    mat_sigma_graded: 1e-6;         // (exact; 8.8e-5; 9e-2 with csx's average; identical material dumps)
    bg_material: 1e-6;              // (exact)
    lorentz_weight: 1e-4;
    debye_weight: 1e-4;
    // Parameters, mesh.
    param_set: 1e-6;                // (exact)
    grid_unsorted: 1e-6;            // (exact)
    grid_deltaunit_m: 1e-6;         // (exact; 1.0e-4; an ulp on the material-boundary coefficients)
    // Excitations.
    exc_weight: 1e-6;               // (exact)
    exc_sphere: 1e-6;               // (exact)
    exc_disabled: 1e-6;             // (exact)
    // Probes.
    probe_two_prims: 1e-6;          // (exact)
    probe_transformed: 1e-6;        // (exact)
    probe_cylinder_prim: 1e-6;      // (exact)
    probe_e_box: 1e-6;              // (exact)
    probe_fd: 1e-6;                 // (exact; f32 round-off 1.8e-4)
    probe_times: 1e-6;              // (exact)
    probe_polygon_i: 1e-6;          // (exact)
    // Boundaries, absorbing sheets, settings.
    bc_spellings: 1e-6;             // (exact; Mur faces in openEMS's order, §5.16.8)
    // openEMS's PML_8 on every face of a 40³ box, probes 4–12 cells from
    // the layers (8e-3 with the CPML; ems runs openEMS's layer for files).
    pml_open: 1e-6;                 // (exact; 4.0e-6 before openEMS's layer arithmetic, §5.16.8)
    abc_line_s0_t0: 1e-6;           // (exact; 1e-6 before openEMS's sheet arithmetic, §5.16.8)
    abc_line_s1_t1: 1e-6;           // (exact)
    lumped_on_cyl: 1e-6;            // (exact)
    // Conducting sheets: openEMS's sheet model (compile/openems_sheet.rs).
    sheet_copper: 2e-4;
    sheet_resistive: 2e-4;
    sheet_full: 2e-4;
    sheet_graded: 2e-4;
    // Polygon sheets with three oblique sides (copper, σt = 0.1 S).
    sheet_triangle: 2e-4;
    sheet_triangle_r: 2e-4;
    fdtd_odd: 1e-4;
    fdtd_ts_and_steps0: 1e-30;      // (the t = 0 row of E-type files)
}

#[cfg(feature = "hdf5")]
cases! {
    dump_nomode: 1e-5;              // (2e-6)
    dump_optres2: 1e-5;
    dump_two_prims: 1e-5;
    dump_transformed: 1e-6;         // (exact)
}
